import{_ as s,o as i,c as e,ag as a}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"SetSimDO8421 设置8421码虚拟数字量输出","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/4. IO 指令/SetSimDO8421.md","filePath":"3. 指令/4. IO 指令/SetSimDO8421.md","lastUpdated":1778862643000}'),l={name:"3. 指令/4. IO 指令/SetSimDO8421.md"};function n(d,t,r,h,o,p){return i(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="setsimdo8421-设置8421码虚拟数字量输出" tabindex="-1">SetSimDO8421 设置8421码虚拟数字量输出 <a class="header-anchor" href="#setsimdo8421-设置8421码虚拟数字量输出" aria-label="Permalink to &quot;SetSimDO8421 设置8421码虚拟数字量输出&quot;">​</a></h1><p>该指令用于设置一段连续的**虚拟数字量输出（SimDO）**端口状态。它将传入的一个十进制数值转换成二进制数据，并按位分配到指定的连续 SimDO 端口上。由于是虚拟端口，该操作主要用于程序内部的逻辑分组控制、多位状态标志位的批量设置或与并行后台程序的通讯。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p><code>SetSimDO8421 (BEGINPORT, ENDPORT, SETVALUE)</code></p><p><code>SetSimDO8421 (起始端口, 结束端口, 设置值)</code></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>BEGINPORT</td><td>int</td><td>该段连续虚拟数字量输出端口的起始端口号</td><td>必填</td></tr><tr><td>ENDPORT</td><td>int</td><td>该段连续虚拟数字量输出端口的结束端口号</td><td>必填</td></tr><tr><td>SETVALUE</td><td>int 或 INT 变量</td><td>需要设置的十进制目标值，系统将其转换为二进制按位赋值</td><td>必填</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetSimDO8421</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析：</strong></p><ol><li><strong>目标值转换</strong>：十进制数 <strong>255</strong> 转换为二进制为 <code>1111 1111</code>（共 8 位）。</li><li><strong>执行结果</strong>：将第 <strong>9</strong> 到第 <strong>16</strong> 号虚拟数字量输出端口（共 8 个端口）全部设置为 <strong>1</strong>。</li></ol><p><strong>示例 2：批量设置状态位</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetSimDO8421</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析：</strong></p><ol><li><strong>目标值转换</strong>：十进制数 <strong>5</strong> 转换为 4 位二进制为 <code>0101</code>。</li><li><strong>端口分配</strong>（起始端口 1 为最低位）： <ul><li>SimDO1 = 1</li><li>SimDO2 = 0</li><li>SimDO3 = 1</li><li>SimDO4 = 0</li></ul></li></ol><hr><h3 id="💡-虚拟与物理-8421-指令的区别" tabindex="-1"><strong>💡 虚拟与物理 8421 指令的区别</strong> <a class="header-anchor" href="#💡-虚拟与物理-8421-指令的区别" aria-label="Permalink to &quot;**💡 虚拟与物理 8421 指令的区别**&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">指令类型</th><th style="text-align:left;">适用对象</th><th style="text-align:left;">硬件影响</th><th style="text-align:left;">典型用途</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SetDO8421</strong></td><td style="text-align:left;">物理 DO 端口</td><td style="text-align:left;">直接改变控制器接线端子的输出电平</td><td style="text-align:left;">驱动外部 PLC、显示器、阀组</td></tr><tr><td style="text-align:left;"><strong>SetSimDO8421</strong></td><td style="text-align:left;">虚拟 SimDO 端口</td><td style="text-align:left;">仅改变控制器内部寄存器状态</td><td style="text-align:left;">逻辑判断、程序间通讯、仿真调试</td></tr></tbody></table>',21)])])}const c=s(l,[["render",n]]);export{k as __pageData,c as default};
